  'sushi_go-box':{src:'assets/real/sushi-go-box.jpg',title:L('Sushi Go! · original tin','Sushi Go! · lata original'),owner:'Gamewright · Nan Rangsima',url:'https://gamewright.com/product/Sushi-Go',group:'sushi_go',width:714,height:1000},
